// Generated by npm run build:browser; edit scripts/database/content.ts.
(()=>{
"use strict";
const tables = ['books', 'sections', 'places', 'sources', 'place_descriptions', 'place_references', 'excerpts', 'unlocated_settings', 'content_translations'];
// Reconstruct the unchanged browser contract from relational rows.
function reconstruct(bundle, id) {
    // Pasting SQL on Windows can turn literal line breaks into CRLF.
    const own = (table) => bundle.tables[table].filter(r => (table === 'books' ? r.id : r.book_id) === id).map(row => Object.fromEntries(Object.entries(row).map(([key, value]) => [key, typeof value === 'string' ? value.replaceAll('\r\n', '\n') : value])));
    const book = own('books')[0];
    if (!book)
        throw new Error(`Unknown book: ${id}`);
    const sourceMap = new Map(own('sources').map(s => [s.id, s]));
    function source(sourceId) { const s = sourceMap.get(sourceId); if (!s)
        throw new Error(`Missing source: ${sourceId}`); return { ...s.metadata, url: s.url, ...(s.label !== null ? { label: s.label } : {}) }; }
    const coords = new Map(own('places').map(p => {
        if (p.latitude === null || p.longitude === null) {
            if (p.latitude !== null || p.longitude !== null)
                throw new Error(`Incomplete coordinates for ${id}/${p.id}`);
            return [p.id, null];
        }
        return [p.id, [p.latitude, p.longitude]];
    }));
    const data = { book: { ...book.metadata, id: book.id, title: book.title, author: book.author }, chapters: [], places: {}, citedPlaces: {} };
    for (const p of own('place_descriptions')) {
        const metadata = p.metadata, coordinates = coords.get(p.place_id), shape = metadata.geometry;
        if (coordinates === undefined || coordinates === null && !['MultiLineString', 'Unresolved'].includes(String(shape?.type)))
            throw new Error(`Place ${id}/${p.place_id} has no renderable or explicitly unresolved geometry`);
        const place = { ...metadata, name: p.name, area: p.area, kind: p.kind, zoom: p.zoom, checked: p.checked instanceof Date ? p.checked.toISOString().slice(0, 10) : String(p.checked).slice(0, 10), status: p.status, note: p.note, method: p.method, coords: coordinates, positionSource: source(p.position_source_id), ...(p.narrative_source_id ? { narrativeSource: source(p.narrative_source_id) } : {}), ...(p.additional_source_id ? { additionalSource: source(p.additional_source_id) } : {}) };
        (p.collection === 'core' ? data.places : data.citedPlaces)[p.place_id] = place;
    }
    function group(sectionId, refId) {
        const rows = own('excerpts').filter(q => q.section_id === sectionId && q.reference_id === refId);
        if (!rows.length)
            return undefined;
        const result = { translations: {} };
        for (const q of rows) {
            const passage = { ...q.metadata, quote: q.quote, language: q.language, type: q.type, attribution: q.attribution, url: source(q.text_source_id).url, rightsUrl: source(q.rights_source_id).url };
            if (id === 'sound-and-fury' && q.slot === 'original') {
                const preferred = q.metadata?.geoCitationTransferRev23;
                if (typeof preferred?.shortEnglishFromWorkbook === 'string') passage.quote = preferred.shortEnglishFromWorkbook;
            }
            if (q.slot === 'original')
                result.original = passage;
            else
                result.translations[q.slot] = passage;
        }
        return result;
    }
    for (const s of own('sections').sort((a, b) => Number(a.ordinal) - Number(b.ordinal))) {
        const c = { ...s.metadata, id: s.id, title: s.title }, fields = s.legacy_fields;
        for (const field of fields)
            c[field] = ['places', 'placeText', 'citations', 'unlocatedPlaces'].includes(field) ? [] : {};
        if (fields.includes('excerpts'))
            c.excerpts = group(s.id, null);
        for (const r of own('place_references').filter(r => r.section_id === s.id).sort((a, b) => Number(a.ordinal) - Number(b.ordinal))) {
            const metadata = r.metadata, placeId = r.place_id;
            if (r.collection === 'core') {
                c.places.push(placeId);
                c.placeText.push(r.scene_text);
                if (metadata.narrativeDescription) {
                    c.placeNarrativeDescriptions ??= {};
                    c.placeNarrativeDescriptions[placeId] = metadata.narrativeDescription;
                }
                if (metadata.explicitCategory)
                    c.placeCategories[placeId] = r.category;
                if (metadata.role !== undefined)
                    c.placeRoles[placeId] = metadata.role;
                if (metadata.quote !== undefined)
                    c.placeQuotes[placeId] = metadata.quote;
                if (r.source_id)
                    c.placeSources[placeId] = source(r.source_id);
                const excerpt = group(s.id, r.id);
                if (excerpt)
                    (c.placeExcerpts ??= {})[placeId] = excerpt;
            }
            else
                c.citations.push({ ...metadata, ...(typeof r.scene_text === 'string' && r.scene_text.trim() ? { scene: r.scene_text } : {}), placeId, category: r.category, excerpt: group(s.id, r.id) });
        }
        for (const u of own('unlocated_settings').filter(u => u.section_id === s.id).sort((a, b) => Number(a.ordinal) - Number(b.ordinal)))
            c.unlocatedPlaces.push({ ...u.metadata, name: u.name, text: u.description, quote: u.quote, url: source(u.source_id).url, settingOrdinal: Number(u.ordinal) });
        data.chapters.push(c);
    }
    // Faulkner REV23: preserve original database records and expose the selected
    // trilingual passages in an unmapped literary-reference section.
    if (id === 'sound-and-fury') {
        const review = data.book.geoReconciliationRev22, transfer = data.book.geoCitationTransferRev23;
        const links = review?.references, registry = transfer?.citations;
        if (Array.isArray(links) && registry) {
            const byId = new Map(own('excerpts').map(e => [String(e.id), e]));
            const chapters = new Map(data.chapters.map(c => [Number(c.id), c]));
            function selected(excerptId, exact) {
                if (typeof excerptId !== 'string' || typeof exact !== 'string' || !exact.trim()) return undefined;
                const row = byId.get(excerptId);
                if (!row) return undefined;
                return { ...row.metadata, quote: exact, language: row.language, type: row.type,
                    attribution: row.attribution, url: source(row.text_source_id).url,
                    rightsUrl: source(row.rights_source_id).url };
            }
            for (const link of links) {
                if (link.target === 'place_references') continue;
                const key = String(link.refId || ''), entry = registry[key];
                if (!entry) continue;
                const chapter = chapters.get(Number(entry.section));
                if (!chapter?.unlocatedPlaces) continue;
                const en = selected(entry.englishExcerptId, entry.shortOriginal),
                    it = selected(entry.italianExcerptId, entry.shortItalian),
                    es = selected(entry.spanishExcerptId, entry.shortSpanish);
                if (!en || !it || !es) continue;
                const existing = link.target === 'unlocated_settings'
                    ? chapter.unlocatedPlaces.find(item => item.settingOrdinal === Number(link.ordinal))
                    : undefined;
                const label = String(entry.placeIdWorkbook || key).replace(/^PL-/, '').replaceAll('_', ' ').toLowerCase();
                chapter.unlocatedPlaces.push({
                    id: 'rev23:' + key,
                    name: existing?.name || label.charAt(0).toUpperCase() + label.slice(1),
                    text: existing?.text || 'Riferimento geografico nel capitolo senza localizzazione puntuale.',
                    quote: en.quote, url: en.url, excerpt: { original: en, translations: { it, es } },
                    rev23Multilingual: true, referenceId: key, displayInAtlas: true
                });
            }
        }
    }
    const dictionary = {};
    for (const row of own('content_translations')) {
        dictionary[row.language] ??= {};
        dictionary[row.language][row.source_text] = row.translated_text;
    }
    return { data, dictionary };
}

window.atlasContent={tables,reconstruct};
})();
